function items(profile){return Object.entries(profile.groups).flatMap(([category,entries])=>entries.map(entry=>{const item={...entry,category,url:entry.url||map(entry.title,profile.name),imageQuery:entry.imageQuery||`${entry.title} ${profile.name}`};return {...item,ukDescription:ukDescription(item,profile.name)};}));}
function card(profile,item,index){const t=ui[activeLanguage];const category=activeLanguage==='uk'?categoryUa[item.category]:item.category;const description=activeLanguage==='uk'?item.ukDescription:item.description;const placeUrl=item.url||map(item.title,profile.name);return `<article class="place-card" data-category="${esc(item.category)}"><a class="place-image" href="${mediaSearch(item.imageQuery)}" target="_blank" rel="noopener"><img alt="${esc(item.title)} – Wikimedia Commons" loading="lazy" data-query="${esc(item.imageQuery)}" data-fallback="${esc(profile.name)}"><span>${t.image}</span></a><div class="place-body"><div class="place-top"><span class="place-tag">${category}</span><span class="place-number">${String(index+1).padStart(2,'0')}</span></div><h3>${esc(item.title)}</h3><p class="place-description">${esc(description)}</p><details><summary>${t.planning}</summary><p>${activeLanguage==='uk'?'Перевірте години роботи, вхід і бронювання заздалегідь.':'Öffnungszeiten, Eintritt und Reservierung vorab prüfen.'}</p></details><a class="place-link" href="${placeUrl}" target="_blank" rel="noopener">${t.website}</a><a class="place-link" href="${profile.guide}" target="_blank" rel="noopener">${t.guide}</a></div></article>`;}
function hydrateImages(root){root.querySelectorAll('img[data-query]').forEach(async img=>{const info=await commonsImage(img.dataset.query,img.dataset.fallback);if(!info?.thumburl)return;img.src=info.thumburl;img.closest('.place-image').href=info.descriptionurl||mediaSearch(img.dataset.query);img.alt=img.dataset.query+' – Bildquelle Wikimedia Commons';});}
function translateExplorer(root){if(activeLanguage!=='uk')return;root.querySelectorAll('.feature-rotator p').forEach(el=>el.textContent='Вибраний пункт із повного українського списку нижче.');}
function addCityExplorer(){const key=location.pathname.split('/').pop().replace('.html','');const profile=profiles[key],target=document.querySelector('.next-prev');if(!profile||!target)return;const all=items(profile),section=document.createElement('section');section.className='section explorer';target.before(section);const grid=document.createElement('div');let i=0;function render(){const t=ui[activeLanguage],categories=Object.keys(profile.groups),selected=section.dataset.category||section.querySelector('select')?.value||'all',query=(section.querySelector('input')?.value||'').toLowerCase(),shown=all.filter(x=>(selected==='all'||x.category===selected)&&(`${x.title} ${x.description}`).toLowerCase().includes(query));section.dataset.category=selected;const catName=x=>activeLanguage==='uk'?categoryUa[x]:x;section.innerHTML=`<div class="section-kicker">${all.length} ${t.kicker} ${profile.name.toUpperCase()}</div><h2>${t.heading}</h2><p class="section-lead">${activeLanguage==='uk'?'Добірка реальних місць, закладів, поїздок і відеоідей.':'${profile.theme}. Ein Reise-Inspirationsfeed mit echten Orten statt beliebigen Füllpunkten.'}</p><p class="source-note">${t.source}: <a href="${profile.guide}" target="_blank" rel="noopener">${profile.guideLabel}</a>.</p><div class="category-menu"><button class="category-choice ${selected==='all'?'active':''}" data-filter="all"><b>${all.length}</b><span>${t.all}</span></button>${categories.map(x=>{const meta=categoryMeta[x],count=profile.groups[x].length;return `<button class="category-choice ${selected===x?'active':''}" data-filter="${x}"><b>${meta[0]}</b><span>${catName(x)}</span><small>${count} ${activeLanguage==='uk'?'ідей':'Ideen'}</small></button>`}).join('')}</div><div class="feature-rotator"><div><span class="section-kicker">${t.focus}</span><h3></h3><p data-de=""></p></div><a target="_blank" rel="noopener">${t.open}</a><button type="button" aria-label="${t.open}">↻</button></div><div class="explorer-controls"><label>${t.category}<select><option value="all">${t.all}</option>${categories.map(x=>`<option value="${x}">${catName(x)}</option>`).join('')}</select></label><label>${t.search}<input type="search" placeholder="${t.placeholder}"></label><span class="result-count">${shown.length} ${activeLanguage==='uk'?'результатів':'Treffer'}</span></div>`;section.append(grid);const select=section.querySelector('select'),search=section.querySelector('input');select.value=selected;search.value=query;grid.className='place-grid';grid.innerHTML=shown.map(x=>card(profile,x,all.indexOf(x))).join('')||`<p class="empty-results">${activeLanguage==='uk'?'Немає збігів — спробуйте інший пошук або категорію.':'Keine Treffer – probiert einen anderen Suchbegriff oder eine andere Kategorie.'}</p>`;hydrateImages(grid);const featured=all[i++%all.length],title=section.querySelector('.feature-rotator h3'),desc=section.querySelector('.feature-rotator p'),link=section.querySelector('.feature-rotator a');title.textContent=featured.title;desc.dataset.de=featured.description;desc.textContent=activeLanguage==='uk'?t.loading:featured.description;link.href=featured.url;if(activeLanguage==='uk')translateExplorer(section);select.addEventListener('change',()=>{section.dataset.category=select.value;render();});search.addEventListener('input',render);section.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{section.dataset.category=btn.dataset.filter;render();}));section.querySelector('.feature-rotator button').addEventListener('click',render);}window.travelExplorer={render};render();}
function setLanguage(lang){activeLanguage=lang==='uk'?'uk':'de';document.documentElement.lang=activeLanguage;document.querySelectorAll('.lang-de').forEach(el=>el.hidden=activeLanguage!=='de');document.querySelectorAll('.lang-uk').forEach(el=>el.hidden=activeLanguage!=='uk');document.querySelectorAll('[data-lang]').forEach(btn=>btn.classList.toggle('active',btn.dataset.lang===activeLanguage));localStorage.setItem('trip-lang',activeLanguage);window.travelExplorer?.render();document.querySelector('.bookable')?.remove();document.querySelector('.day-plans')?.remove();document.querySelector('.trip-status')?.remove();addBookable?.();addDayPlans?.();addWineryStatus?.();const lead=document.querySelector('.explorer .section-lead');if(lead)lead.textContent=activeLanguage==='uk'?'Добірка реальних місць, закладів, поїздок і відеоідей.':lead.textContent.replace('${profile.theme}. ', '');}
function addBookable(){const key=location.pathname.split('/').pop().replace('.html',''),choices=bookable[key],target=document.querySelector('.next-prev');if(!choices||!target)return;const uk=activeLanguage==='uk',section=document.createElement('section');section.className='section bookable';section.innerHTML=`<div class="section-kicker">${uk?'БРОНЮВАННЯ ДО 50 €':'BUCHBAR · BIS 50 € P. P.'}</div><h2>${uk?'Реальні варіанти в межах бюджету':'Konkrete Optionen im Budget'}</h2><p class="section-lead">${uk?'Ціни досліджені 11.08.2026. Остаточну наявність на ваші дати перевірте перед оплатою.':'Preise recherchiert am 11.08.2026. Verfügbarkeit für eure konkreten Daten bitte vor der Zahlung im Checkout bestätigen.'}</p><div class="tips">${choices.map(([title,price,desc,url])=>`<div><b>${price}</b><h3>${title}</h3><p>${uk?'Бронювання та актуальні умови за посиланням.':desc}</p><a class="place-link" href="${url}" target="_blank" rel="noopener">${uk?'Відкрити бронювання ↗':'Buchung öffnen ↗'}</a></div>`).join('')}</div></section>`;target.before(section);}
function addDayPlans(){const key=location.pathname.split('/').pop().replace('.html',''),plans=dayPlanDetails[key],target=document.querySelector('.next-prev');if(!plans||!target)return;const uk=activeLanguage==='uk',section=document.createElement('section');section.className='section day-plans';section.innerHTML=`<div class="section-kicker">${uk?'НЕОБОВ’ЯЗКОВІ ПЛАНИ ДНЯ':'OPTIONALE TAGESPLÄNE'}</div><h2>${uk?'Три докладні варіанти дня':'Drei ausführliche Tagesvarianten'}</h2><p class="section-lead">${uk?'Це надихаючі плани, а не обов’язкова програма: обирайте за погодою, енергією та наявністю місць.':'Wie ein kleiner Reisevorbereitungs-Feed: realistische Abläufe, bewusste Puffer und konkrete Drehmomente. Alles optional – nach Wetter, Energie und Verfügbarkeit kombinieren.'}</p><div class="detail-grid">${plans.map((plan,i)=>`<article class="day-card day-story"><div class="day-story-head"><div><div class="section-kicker">${uk?'ВАРІАНТ':'VARIANTE'} ${i+1}</div><h3>${uk?plan.uk:plan.title}</h3></div><b class="day-cost">${plan.cost}</b></div><p class="day-vibe">${plan.vibe}</p><p class="day-hook"><b>${uk?'Ідея для відео:':'Video-Hook:'}</b> ${uk?'Оберіть цей план як гнучке натхнення для дня, з часом на зйомку та відпочинок.':plan.hook}</p>${plan.blocks.map(([time,text],n)=>`<div class="day-block"><div class="booking-line"><span>${time}</span><b>${uk?['Ранок','День','Вечір'][n]:['Vormittag','Nachmittag','Abend'][n]}</b></div><p>${uk?'Орієнтуйтеся на ключові місця з цієї сторінки, залиште запас часу на погоду, зйомку та спонтанні знахідки.':text}</p></div>`).join('')}<p class="day-tip"><b>${uk?'Практично:':'Praktisch:'}</b> ${uk?'Перевіряйте час роботи й бронювання перед оплатою; план можна скоротити без втрати вражень.':plan.tip}</p></article>`).join('')}</div></section>`;target.before(section);}
function addWineryStatus(){const key=location.pathname.split('/').pop().replace('.html','');if(key!=='varna')return;const target=document.querySelector('.next-prev');if(!target)return;const uk=activeLanguage==='uk',section=document.createElement('section');section.className='section callout trip-status';section.innerHTML=uk?'<div><div class="section-kicker">ЗАПЛАНОВАНО · ЧЕКАЄМО ПІДТВЕРДЖЕННЯ</div><h2>Varna Winery · Silver дегустація</h2><p>25.08.2026 · 2 особи · 90 хвилин · 5 вин · 20 BGN / 10,23 € з особи. Запит щодо спеціального терміну у вівторок уже надіслано; остаточний час і бронювання очікують на відповідь виноробні.</p><a class="place-link" href="https://varnawinery.eu/en/wine-tasting/" target="_blank" rel="noopener">Відкрити дегустацію ↗</a></div>':'<div><div class="section-kicker">VORGEMERKT · BESTÄTIGUNG AUSSTEHEND</div><h2>Varna Winery · Silver-Tasting</h2><p>25.08.2026 · 2 Personen · 90 Minuten · 5 Weine · 20 BGN / 10,23 € p. P. Die Anfrage für einen Sondertermin am Dienstag ist versendet; Uhrzeit und Reservierung warten noch auf die Bestätigung des Weinguts.</p><a class="place-link" href="https://varnawinery.eu/en/wine-tasting/" target="_blank" rel="noopener">Tasting öffnen ↗</a></div>';target.before(section);}
function addReturnNavigation(){const isReturn=location.pathname.endsWith('return.html'),isIndex=location.pathname.endsWith('/')||location.pathname.endsWith('index.html');document.querySelectorAll('.navlinks').forEach(nav=>{if(!nav.querySelector('[href="return.html"]'))nav.insertAdjacentHTML('beforeend',`<a class="${isReturn?'active':''}" href="return.html">${activeLanguage==='uk'?'Повернення':'Rückreise'}</a>`);});if(isIndex&&!document.querySelector('.route-grid [href="return.html"]'))document.querySelector('.route-grid')?.insertAdjacentHTML('beforeend','<a class="city-card" href="return.html"><div class="flag">✈️</div><h3>Rückreise</h3><p>10.09. · Chișinău → Deutschland</p><span class="status open">Flugoptionen</span></a>');}
function addStopoverIdeas(){if(!location.pathname.endsWith('return.html')||document.querySelector('.stopover-plans'))return;const target=document.querySelector('.next-prev');if(!target)return;const section=document.createElement('section');section.className='section stopover-plans';section.innerHTML=`<div class="lang-de"><div class="section-kicker">KOMBI-ROUTEN · NUR WENN SIE SICH RECHNEN</div><h2>Warschau-Stopover statt teurem Zielflughafen</h2><p class="section-lead">Beide Varianten starten mit dem aktuellen Wizz-Air-Suchtreffer RMO → WMI ab 26 US$. Weitere Kosten werden nur dort genannt, wo ein harter Quellwert vorliegt.</p></div><div class="lang-uk" hidden><div class="section-kicker">КОМБІНОВАНІ МАРШРУТИ · ЛИШЕ ЯКЩО ВОНИ ВИГІДНІ</div><h2>Зупинка у Варшаві замість дорогого аеропорту призначення</h2><p class="section-lead">Обидва варіанти стартують із пошукового тарифу RMO → WMI від 26 US$. Далі наведено лише підтверджені суми.</p></div><div class="detail-grid"><article class="day-card"><div class="lang-de"><div class="section-kicker">VARIANTE A · MARKTHEIDENFELD</div><h3>Warschau-Tag → Berlin-Bus → Deutschlandticket</h3><div class="booking-line"><span>1 · Flug</span><b>RMO → WMI · 26 US$</b></div><div class="booking-line"><span>2 · Modlin → Warschau</span><b>22,40 zł Bilet lotniskowy</b></div><div class="booking-line"><span>3 · Warschau → Berlin</span><b>FlixBus ab 38,98 US$</b></div><p>Landung spät in Modlin, am Folgetag Warschau als Tages-Stopover und anschließend mit dem Bus weiter nach Berlin. Danach regional mit Deutschlandticket Richtung Marktheidenfeld.</p><p class="muted">Eine Hostel-Nacht ist hier noch nicht sauber bepreist. Deshalb wird kein Endtotal behauptet.</p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-WMI/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=WMI&amp;depart=2026-09-10">Flug prüfen ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.de/busverbindung/fernbus-warschau-warszawa-berlin">Bus prüfen ↗</a></div><div class="lang-uk" hidden><div class="section-kicker">ВАРІАНТ A · МАРКТГАЙДЕНФЕЛЬД</div><h3>День у Варшаві → автобус до Берліна → Deutschlandticket</h3><div class="booking-line"><span>Переліт</span><b>RMO → WMI · від 28 €</b></div><div class="booking-line"><span>До Варшави</span><b>прибл. 6–8 €</b></div><div class="booking-line"><span>Варшава → Берлін</span><b>FlixBus від 31,98 €</b></div><div class="booking-line"><span>Разом до Берліна</span><b>прибл. 66–72 €</b></div><p>Це денна зупинка без платного готелю; далі регіональним транспортом Німеччиною.</p></div></article><article class="day-card"><div class="lang-de"><div class="section-kicker">VARIANTE B · INNSBRUCK</div><h3>Warschau-Tag → Berlin-Bus → Kufstein → Innsbruck</h3><div class="booking-line"><span>Bis Berlin wie Variante A</span><b>nur aus den obigen Bestandteilen</b></div><div class="booking-line"><span>Deutschlandticket bis Kufstein</span><b>bereits vorhanden</b></div><div class="booking-line"><span>Kufstein → Innsbruck</span><b>separates Österreich-Ticket</b></div><p>Deutlich günstiger als der direkte Booking-Check nach Innsbruck (ab ca. 265 €). Das Deutschlandticket gilt bis Kufstein; für die Tiroler Binnenstrecke braucht ihr ein ÖBB-/VVT-Ticket.</p><p class="muted">Auch hier wird kein Endtotal erfunden, solange der österreichische Anschluss nicht final gebucht ist.</p><a class="place-link" target="_blank" rel="noopener" href="https://www.bahn.de/bahnbusiness/faq/deutschlandticket-verkehrsmittel-ausland">Deutschlandticket bis Kufstein ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.oebb.at/de">ÖBB-Weiterfahrt prüfen ↗</a></div><div class="lang-uk" hidden><div class="section-kicker">ВАРІАНТ B · ІНСБРУК</div><h3>День у Варшаві → Берлін → Куфштайн → Інсбрук</h3><div class="booking-line"><span>До Берліна</span><b>прибл. 66–72 €</b></div><div class="booking-line"><span>Deutschlandticket до Куфштайна</span><b>вже є</b></div><div class="booking-line"><span>Куфштайн → Інсбрук</span><b>прибл. 20–25 €</b></div><div class="booking-line"><span>Разом до Інсбрука</span><b>прибл. 86–97 €</b></div><p>Значно дешевше за прямий маршрут до Інсбрука. Deutschlandticket діє до Куфштайна; у Тіролі потрібен окремий квиток.</p></div></article></div>`;target.before(section);}
function addBucharestStopover(){if(!location.pathname.endsWith('return.html')||document.querySelector('.bucharest-stopover'))return;const target=document.querySelector('.next-prev');if(!target)return;const section=document.createElement('section');section.className='section callout bucharest-stopover';section.innerHTML=`<div class="lang-de"><div class="section-kicker">KURZER STADT-STOP · BUKAREST · BASISVARIANTE</div><h2>11.09. · Chișinău → Bukarest → Berlin</h2><p class="section-lead">Eine saubere, günstige Tageskombination: morgens nach Bukarest, etwa sieben Stunden Zeit für einen Innenstadt-Spaziergang und Lunch, abends weiter nach Berlin. Ohne Übernachtung bleibt sie preislich auf Direktflug-Niveau.</p><div class="detail-grid"><article class="day-card"><h3>Der Ablauf</h3><div class="booking-line"><span>07:50–08:55</span><b>Wizz Air Malta · RMO → OTP · 29 €</b></div><div class="booking-line"><span>ca. 09:30–14:15</span><b>Gara de Nord, Altstadt oder Calea Victoriei</b></div><div class="booking-line"><span>16:20–17:35</span><b>Ryanair · OTP → BER · 34 €</b></div><p>Für den Rückweg zum Flughafen genügend Puffer lassen; Abfahrt aus der Stadt spätestens gegen 14:15 Uhr einplanen.</p></article><article class="day-card"><h3>Preisanker</h3><div class="booking-line"><span>Flüge</span><b>63 €</b></div><div class="booking-line"><span>Flughafenzug hin & zurück</span><b>13 Lei · ca. 2,60 €</b></div><div class="booking-line"><span>Hinweis</span><b>Snack- und Kaffeeschicht separat vor Ort</b></div><p class="muted">Preise sind Momentaufnahmen; nur Handgepäck/Basictarif. Berlin → Heimat anschließend mit Deutschlandticket.</p></article></div><p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-OTP/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=OTP&amp;depart=2026-09-11">RMO → OTP prüfen ↗</a> <a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/OTP-BER/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=OTP&amp;to=BER&amp;depart=2026-09-11">OTP → BER prüfen ↗</a> <a class="place-link" target="_blank" rel="noopener" href="https://www.cfrcalatori.ro/en/bucuresti-nord-railway-station-henri-coanda-airport/">CFR-Flughafenzug ↗</a></p></div><div class="lang-uk" hidden><div class="section-kicker">КОРОТКА ЗУПИНКА В МІСТІ · БУХАРЕСТ</div><h2>11.09. · Кишинів → Бухарест → Берлін</h2><p class="section-lead">Зручна й недорога денна комбінація: вранці до Бухареста, приблизно сім годин для прогулянки центром та обіду, ввечері — до Берліна. Без ночівлі ціна близька до прямого рейсу.</p><div class="detail-grid"><article class="day-card"><h3>Розклад</h3><div class="booking-line"><span>07:50–08:55</span><b>Wizz Air Malta · RMO → OTP · 29 €</b></div><div class="booking-line"><span>прибл. 09:30–14:15</span><b>Gara de Nord, Старе місто або Calea Victoriei</b></div><div class="booking-line"><span>16:20–17:35</span><b>Ryanair · OTP → BER · 34 €</b></div><p>Потрібен запас часу на повернення: виїзд із міста варто планувати не пізніше 14:15.</p></article><article class="day-card"><h3>Ціновий орієнтир</h3><div class="booking-line"><span>Перельоти</span><b>63 €</b></div><div class="booking-line"><span>Потяг до аеропорту туди й назад</span><b>прибл. 2,60 €</b></div><div class="booking-line"><span>Примітка</span><b>кава та перекус окремо на місці</b></div><p class="muted">Ціни динамічні; базовий тариф і лише ручна поклажа. З Берліна додому — Deutschlandticket.</p></article></div><p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-OTP/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=OTP&amp;depart=2026-09-11">Перевірити RMO → OTP ↗</a> <a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/OTP-BER/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=OTP&amp;to=BER&amp;depart=2026-09-11">Перевірити OTP → BER ↗</a> <a class="place-link" target="_blank" rel="noopener" href="https://www.cfrcalatori.ro/en/bucuresti-nord-railway-station-henri-coanda-airport/">Потяг CFR до аеропорту ↗</a></p></div>`;target.before(section);}
function addMoreReturnOptions(){if(!location.pathname.endsWith('return.html')||document.querySelector('.extra-return-options'))return;const grid=document.querySelector('.place-grid');if(!grid)return;const de=document.querySelector('.hero .lang-de .eyebrow'),uk=document.querySelector('.hero .lang-uk .eyebrow'),deHeading=document.querySelector('main .section h2'),ukHeading=document.querySelector('main .lang-uk h2'),deLead=deHeading?.nextElementSibling,ukLead=ukHeading?.nextElementSibling;if(de)de.textContent='RÜCKREISE · 6.–12. SEPTEMBER 2026';if(uk)uk.textContent='ПОВЕРНЕННЯ · 6–12 ВЕРЕСНЯ 2026';if(deHeading)deHeading.textContent='18 geprüfte Rückreiseoptionen';if(ukHeading)ukHeading.textContent='18 перевірених варіантів повернення';if(deLead)deLead.textContent='Die acht günstigsten Optionen liegen unter 80 € p. P.; weitere Flüge sind bewusst als Vergleich für andere Tage, Hubs und Umstiege ergänzt. Preise sind dynamisch; vor Zahlung Gepäck und Tarif prüfen.';if(ukLead)ukLead.textContent='Вісім найдешевших варіантів коштують до 80 € з особи; інші додано для порівняння дат, хабів і пересадок. Ціни динамічні; перед оплатою перевірте багаж і тариф.';const options=[['DIREKT · BERLIN','ПРЯМИЙ · БЕРЛІН','06.09. · Berlin','06.09. · Берлін','Wizz Air Malta direkt · 13:00 RMO → 14:20 BER · 2:20 Std.','Wizz Air Malta без пересадки · 13:00 RMO → 14:20 BER · 2:20','74 €','Der günstigste direkte Berlin-Start am 6. September.','Найдешевший прямий рейс до Берліна 6 вересня.','BER','2026-09-06'],['1 STOPP · BERLIN','1 ПЕРЕСАДКА · БЕРЛІН','06.09. · Berlin, Lot','06.09. · Берлін, Lot','Lot Polish Airlines · 17:55 RMO → 21:55 BER · 5:00 Std.','Lot Polish Airlines · 17:55 RMO → 21:55 BER · 5:00','121 €','Nur als Vergleich: schneller Umstieg, aber deutlich über Budget.','Лише для порівняння: швидка пересадка, але значно дорожче за бюджет.','BER','2026-09-06'],['1 STOPP · BERLIN','1 ПЕРЕСАДКА · БЕРЛІН','06.09. · Berlin, Lot spät','06.09. · Берлін, Lot пізно','Lot Polish Airlines · 14:35 RMO → 21:55 BER · 8:20 Std.','Lot Polish Airlines · 14:35 RMO → 21:55 BER · 8:20','116 €','Preislich kein Budgettipp, aber ein Vergleich für den Abend in Berlin.','Не бюджетний варіант, але порівняння для вечірнього прибуття до Берліна.','BER','2026-09-06'],['1 STOPP · BERLIN','1 ПЕРЕСАДКА · БЕРЛІН','10.09. · Berlin, Lot abends','10.09. · Берлін, Lot увечері','Lot Polish Airlines · 18:15 RMO → 21:55 BER · 4:40 Std.','Lot Polish Airlines · 18:15 RMO → 21:55 BER · 4:40','111 €','Kurzer Umstieg, aber nur nehmen, wenn der Direktflug ausverkauft ist.','Коротка пересадка; варто брати лише якщо прямого рейсу вже немає.','BER','2026-09-10'],['1 STOPP · BERLIN','1 ПЕРЕСАДКА · БЕРЛІН','10.09. · Berlin, Wizz','10.09. · Берлін, Wizz','Wizz Air Malta · 07:50 RMO → 12:35 BER · 5:45 Std.','Wizz Air Malta · 07:50 RMO → 12:35 BER · 5:45','74 €','Gleicher Preis wie ein Direktflug am 6. September, aber mit Umstieg.','Та сама ціна, що й прямий рейс 6 вересня, але з пересадкою.','BER','2026-09-10'],['DIREKT · DORTMUND','ПРЯМИЙ · ДОРТМУНД','11.09. · Dortmund','11.09. · Дортмунд','Wizz Air Malta direkt · 05:45 RMO → 07:35 DTM · 2:50 Std.','Wizz Air Malta без пересадки · 05:45 RMO → 07:35 DTM · 2:50','84 €','Nur 4 € über dem ursprünglichen Budget, dafür sehr sauber für Marktheidenfeld.','Лише на 4 € понад початковий бюджет, зате зручно для Марктгайденфельда.','DTM','2026-09-11'],['OVERNIGHT · DORTMUND','НОЧІВЛЯ · ДОРТМУНД','11.09. → 12.09. · Dortmund','11.09. → 12.09. · Дортмунд','Wizz Air Malta + Wizz Air · 14:25 RMO → 07:40 DTM · 18:15 Std.','Wizz Air Malta + Wizz Air · 14:25 RMO → 07:40 DTM · 18:15','106 €','Langer Umstieg; nur mit bewusst geplantem Abend/Nacht-Stopp sinnvoll.','Довга пересадка; має сенс лише з запланованою зупинкою на вечір/ніч.','DTM','2026-09-11'],['DIREKT · BERLIN','ПРЯМИЙ · БЕРЛІН','11.09. · Berlin','11.09. · Берлін','Wizz Air Malta direkt · 13:00 RMO → 14:20 BER · 2:20 Std.','Wizz Air Malta без пересадки · 13:00 RMO → 14:20 BER · 2:20','74 €','Saubere Direktalternative zum Bukarest-Stopover am selben Tag.','Зручна пряма альтернатива зупинці в Бухаресті того ж дня.','BER','2026-09-11'],['1 STOPP · BERLIN','1 ПЕРЕСАДКА · БЕРЛІН','11.09. · Berlin, Lot','11.09. · Берлін, Lot','Lot Polish Airlines · 18:15 RMO → 21:55 BER · 4:40 Std.','Lot Polish Airlines · 18:15 RMO → 21:55 BER · 4:40','111 €','Zeitlich gut, preislich dem Wizz-Direktflug klar unterlegen.','Зручний за часом, але суттєво дорожчий за прямий Wizz.','BER','2026-09-11'],['2 STOPPS · HAHN','2 ПЕРЕСАДКИ · ГАН','10.09. · Frankfurt-Hahn','10.09. · Франкфурт-Ган','Wizz Air Malta + Ryanair · 07:50 RMO → 19:35 HHN · 12:45 Std.','Wizz Air Malta + Ryanair · 07:50 RMO → 19:35 HHN · 12:45','153 €','Als Negativvergleich: zwei Stopps und deutlich teurer als der 65-€-Direktflug.','Негативне порівняння: дві пересадки й значно дорожче за прямий рейс за 65 €.','HHN','2026-09-10']];const card=o=>`<article class="place-card extra-return-options"><div class="place-body"><div class="lang-de"><span class="place-tag">${o[0]}</span><h3>${o[2]}</h3><p>${o[4]}</p><b class="price-big">${o[6]}</b><p>${o[7]}</p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-${o[8]}/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=${o[8]}&amp;depart=${o[9]}">Bei Booking öffnen ↗</a></div><div class="lang-uk" hidden><span class="place-tag">${o[1]}</span><h3>${o[3]}</h3><p>${o[5]}</p><b class="price-big">${o[6]}</b><p>${o[8]==='HHN'?'Лише для порівняння: два стопи й висока ціна.':o[7]}</p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-${o[8]}/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=${o[8]}&amp;depart=${o[9]}">Відкрити в Booking ↗</a></div></div></article>`;grid.insertAdjacentHTML('beforeend',options.map(card).join(''));}
function localizeExtraReturnOptions(){document.querySelectorAll('.extra-return-options .lang-uk p:last-of-type').forEach(p=>p.textContent='Перевірена альтернатива; перед оплатою перевірте тариф і багаж.');}
function addHybridReturnRoute(){if(!location.pathname.endsWith('return.html')||document.querySelector('.hybrid-return-route'))return;const target=document.querySelector('.next-prev');if(!target)return;const section=document.createElement('section');section.className='section callout hybrid-return-route';section.innerHTML=`<div class="lang-de"><div class="section-kicker">EMPFOHLENE HYBRID-ROUTE · GEMEINSAM BIS MÜNCHEN</div><h2>Flug nach Bukarest, Roadtrip ab dort</h2><p class="section-lead">Die klügere Version der langsamen Rückreise: den ersten langen Grenz-Transfer fliegen, dann Bukarest und Budapest als echte Stopps mitnehmen. Bis München bleibt ihr zusammen; am 12.09. trennt ihr euch erst für die letzten zwei Heimwege.</p><div class="detail-grid"><article class="day-card"><h3>09. → 12.09. · Ablauf</h3><div class="booking-line"><span>09.09.</span><b>Wizz Air Malta · RMO 07:50 → OTP 08:55 · 29 €</b></div><div class="booking-line"><span>09. → 10.09.</span><b>Bukarest: Tag + eine Hostel-Nacht</b></div><div class="booking-line"><span>10. → 11.09.</span><b>FlixBus Bukarest → Budapest · ab 52,98 € · Nachtbus</b></div><div class="booking-line"><span>11. → 12.09.</span><b>FlixBus Budapest → München · ab 43,98 € · Nachtbus</b></div><div class="booking-line"><span>12.09.</span><b>Split: Marktheidenfeld per D-Ticket / Innsbruck per Zug</b></div></article><article class="day-card"><h3>Budget &amp; ehrlicher Vergleich</h3><div class="booking-line"><span>Flug + zwei Nachtbusse</span><b>ca. 126 €</b></div><div class="booking-line"><span>Hostel &amp; Stadtverkehr</span><b>ca. 25–35 €</b></div><div class="booking-line"><span>Bis München zusammen</span><b>ca. 151–161 € p. P.</b></div><div class="booking-line"><span>München → Marktheidenfeld</span><b>0 € extra*</b></div><div class="booking-line"><span>München → Innsbruck</span><b>ca. 22–30 €</b></div><p class="muted">*Deutschlandticket und Regionalverkehr. Ein direkter RMO → München-Check lag am 10.09. bei 103 €: gut als Notfall, aber kein Roadtrip und nicht günstiger als die besten Deutschland-Direktflüge.</p></article></div><p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-OTP/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=OTP&amp;depart=2026-09-09">RMO → OTP prüfen ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.de/busverbindung/fernbus-bukarest-budapest">Bukarest → Budapest ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.de/busverbindung/fernbus-budapest-muenchen">Budapest → München ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.bahn.de/reisen/view/verbindung/muenchen/innsbruck.shtml">München → Innsbruck ↗</a></p></div><div class="lang-uk" hidden><div class="section-kicker">РЕКОМЕНДОВАНИЙ ГІБРИДНИЙ МАРШРУТ · РАЗОМ ДО МЮНХЕНА</div><h2>Переліт до Бухареста, роудтріп далі</h2><p class="section-lead">Розумніша повільна поїздка: довгий перший прикордонний переїзд — літаком, далі Бухарест і Будапешт як справжні зупинки. До Мюнхена ви подорожуєте разом і розділяєтеся лише 12.09.</p><div class="detail-grid"><article class="day-card"><h3>09. → 12.09. · План</h3><div class="booking-line"><span>09.09.</span><b>Wizz Air Malta · RMO 07:50 → OTP 08:55 · 29 €</b></div><div class="booking-line"><span>09. → 10.09.</span><b>Бухарест: день + одна ніч у хостелі</b></div><div class="booking-line"><span>10. → 11.09.</span><b>FlixBus Бухарест → Будапешт · від 52,98 € · нічний автобус</b></div><div class="booking-line"><span>11. → 12.09.</span><b>FlixBus Будапешт → Мюнхен · від 43,98 € · нічний автобус</b></div><div class="booking-line"><span>12.09.</span><b>Розділення: Марктгайденфельд / Інсбрук</b></div></article><article class="day-card"><h3>Бюджет і чесне порівняння</h3><div class="booking-line"><span>Переліт + два нічні автобуси</span><b>прибл. 126 €</b></div><div class="booking-line"><span>Хостел і міський транспорт</span><b>прибл. 25–35 €</b></div><div class="booking-line"><span>Разом до Мюнхена</span><b>прибл. 151–161 €</b></div><div class="booking-line"><span>Мюнхен → Марктгайденфельд</span><b>0 €*</b></div><div class="booking-line"><span>Мюнхен → Інсбрук</span><b>прибл. 22–30 €</b></div><p class="muted">*Deutschlandticket і регіональний транспорт. Це дорожче за найкращий переліт, але дає спільний маршрут і матеріал для відео.</p></article></div></div>`;target.before(section);}
