function syncVerifiedRouteFacts(){const key=location.pathname.split('/').pop().replace('.html','');if(key==='varna'&&bookable?.varna?.[4])bookable.varna[4][2]='90 Minuten, 3–5 Weine; für Dienstag, 25.08., als Fixpunkt eingeplant – Startzeit und Bestätigung prüfen.';if(key==='galati'){const card=document.querySelector('.overview .booking-card:nth-child(2)');if(card)card.innerHTML=`<div class="lang-de"><div class="section-kicker">ANREISE · GEPRÜFTE VERBINDUNG</div><h3>Tulcea → Galați</h3><div class="booking-line"><span>Datum</span><b>28.08. · Freitag</b></div><div class="booking-line"><span>Verbindung</span><b>09:50 → 11:44 · ca. 1:54 Std.</b></div><div class="booking-line"><span>Preis</span><b>60 Lei p. P.</b></div><p class="muted">Der Freitagstermin passt zum aktuellen Betreiberfahrplan; Abfahrtsort und Verfügbarkeit vor Abfahrt nochmals bestätigen.</p></div><div class="lang-uk" hidden><div class="section-kicker">ПРИБУТТЯ · ПЕРЕВІРЕНИЙ РЕЙС</div><h3>Тулча → Галац</h3><div class="booking-line"><span>Дата</span><b>28.08. · п’ятниця</b></div><div class="booking-line"><span>Сполучення</span><b>09:50 → 11:44 · прибл. 1:54 год.</b></div><div class="booking-line"><span>Ціна</span><b>60 леїв з особи</b></div><p class="muted">П’ятничний рейс відповідає актуальному розкладу перевізника; місце відправлення та наявність ще раз перевірити перед поїздкою.</p></div>`;}if(key==='chisinau'){const card=document.querySelector('.overview .booking-card:first-child');if(card)card.innerHTML=`<div class="lang-de"><div class="section-kicker">ANREISE · GEPRÜFTE VERBINDUNG</div><h3>Galați → Chișinău</h3><div class="booking-line"><span>Datum</span><b>29.08. · Nachtbus</b></div><div class="booking-line"><span>Abfahrt</span><b>23:00 · Galați Metropoli</b></div><div class="booking-line"><span>Preis</span><b>380 MDL p. P.</b></div><div class="booking-line"><span>Ankunft</span><b>30.08. · ca. 04:00 Chișinău Südwest</b></div><p class="muted">Damit bleibt der gesamte 29.08. für Galați frei; die Unterkunftsnacht 28.–29.08. einplanen. Die konkrete Haltestelle und Verfügbarkeit vor Abfahrt erneut prüfen.</p></div><div class="lang-uk" hidden><div class="section-kicker">ПРИБУТТЯ · ПЕРЕВІРЕНИЙ РЕЙС</div><h3>Галац → Кишинів</h3><div class="booking-line"><span>Дата</span><b>29.08. · нічний автобус</b></div><div class="booking-line"><span>Відправлення</span><b>23:00 · Galați Metropoli</b></div><div class="booking-line"><span>Ціна</span><b>380 MDL з особи</b></div><div class="booking-line"><span>Прибуття</span><b>30.08. · близько 04:00, Південно-Західний автовокзал</b></div><p class="muted">Так 29.08. повністю залишається для Галаца; ніч 28–29.08. потрібно врахувати. Зупинку та наявність ще раз перевірити перед поїздкою.</p></div>`;}if(key==='galati'||key==='chisinau'||key==='varna'){const target=document.querySelector('.next-prev');if(target&&!document.querySelector('.route-facts-note')){const n=document.createElement('section');n.className='section callout route-facts-note';n.innerHTML='<div class="lang-de"><div class="section-kicker">FAKTENSTATUS · 11.08.2026</div><p>Konkrete Fahrzeiten und Preise sind mit dem aktuell gefundenen Betreiber-/Buchungsstand abgeglichen. Verfügbarkeit, Haltestelle und mögliche Änderungen bitte unmittelbar vor der Fahrt nochmals öffnen.</p></div><div class="lang-uk" hidden><div class="section-kicker">СТАН ФАКТІВ · 11.08.2026</div><p>Конкретний час і ціни звірено з актуальними даними перевізника/бронювання. Наявність, зупинку та можливі зміни ще раз перевірити безпосередньо перед поїздкою.</p></div>';target.before(n);}}}
syncVerifiedRouteFacts();setLanguage(activeLanguage);
function repairUndefinedTags(){document.querySelectorAll('body *').forEach(el=>{if(el.children.length===0&&el.textContent.trim().toLowerCase()==='undefined')el.textContent=el.classList.contains('place-tag')?'Ort':el.tagName==='B'?'00':'Nicht näher bezeichnet';});}
document.querySelectorAll('[data-lang]').forEach(btn=>btn.addEventListener('click',()=>setTimeout(repairUndefinedTags,0)));repairUndefinedTags();new MutationObserver(repairUndefinedTags).observe(document.body,{childList:true,subtree:true});
function addStopoverGems(){if(!location.pathname.endsWith('return.html')||document.querySelector('.stopover-gems'))return;const target=document.querySelector('.bucharest-stopover')||document.querySelector('.next-prev');if(!target)return;const section=document.createElement('section');section.className='section stopover-gems';section.innerHTML=`<div class="lang-de"><div class="section-kicker">ZWEI WEITERE JUWELEN · MAX. 1 ÜBERNACHTUNG</div><h2>Zwischenstopp als Teil der Reise</h2><p class="section-lead">Zwei echte kleine Reisegeschichten mit Stadtzeit, Drehmaterial und einem nachvollziehbaren Weiterweg. Keine Fantasie-Gesamtsummen, nur harte Preisanker.</p><div class="detail-grid"><article class="day-card"><div class="section-kicker">JUWEL 1 · WARSCHAU</div><h3>Modlin spät → Warschau → Berlin</h3><div class="booking-line"><span>10.09. · 22:50–23:35</span><b>Wizz Air · RMO → WMI · 26 US$</b></div><div class="booking-line"><span>10.09. spät</span><b>Modlin → Warschau · 22,40 zł Bilet lotniskowy</b></div><div class="booking-line"><span>11.09.</span><b>Warschau-Walk + FlixBus nach Berlin · ab 38,98 US$</b></div><p>Am Abend nur ankommen und schlafen. Am nächsten Vormittag Altstadt, Weichselufer oder Praga drehen; danach mit dem Bus weiter. Das ist ein richtiger Mini-Roadtrip, kein sinnloser Umstieg.</p><p class="muted">Nicht günstiger als der Direktflug: Das Juwel lebt von Warschau als eigenem Reiseziel. Unterkunft bitte separat im Checkout wählen.</p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-WMI/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=WMI&amp;depart=2026-09-10">RMO → WMI prüfen ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.pl/polaczenia-autobusowe/port-lotniczy-warszawa-modlin-berlin">Modlin → Berlin prüfen ↗</a></article><article class="day-card"><div class="section-kicker">JUWEL 2 · BUKAREST → BUDAPEST</div><h3>Stadt-Stop + Nachtbus entlang der Donau</h3><div class="booking-line"><span>09.09. · 07:50–08:55</span><b>Wizz Air · RMO → OTP · 29 €</b></div><div class="booking-line"><span>09.09. tagsüber</span><b>Bukarest kompakt: Gara de Nord, Calea Victoriei, Altstadt</b></div><div class="booking-line"><span>09.09. abends</span><b>FlixBus · Bukarest → Budapest · ab 52,98 €</b></div><div class="booking-line"><span>10.09.</span><b>Budapest-Tag; Weiterfahrt danach flexibel</b></div><p>Das ist die größere Version des Bukarest-Stops: erst vier Stunden Stadt, dann Nachtbus und am nächsten Morgen direkt Budapest. Ein schöner Donau-Bogen mit nur einer bezahlten Übernachtung – die Busnacht ersetzt das Hostel.</p><p class="muted">Die genaue Nachtbus-Abfahrt und Ankunft sind datumsabhängig; beim Checkout prüfen. Für München kommen ab Budapest aktuell etwa 43,98 € mit FlixBus dazu, für Innsbruck ein separates Österreich-Ticket.</p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-OTP/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=OTP&amp;depart=2026-09-09">RMO → OTP prüfen ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.de/busverbindung/fernbus-bukarest-budapest">Bukarest → Budapest prüfen ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.de/busverbindung/fernbus-budapest-muenchen">Budapest → München prüfen ↗</a></article></div></div><div class="lang-uk" hidden><div class="section-kicker">ЩЕ ДВА ВАРІАНТИ · МАКС. 1 НІЧЛІВЛЯ</div><h2>Пересадка як частина подорожі</h2><p class="section-lead">Це не найдешевші прямі рейси, зате дві справжні міні-подорожі з часом на місто, відео та зрозумілим продовженням маршруту.</p><div class="detail-grid"><article class="day-card"><div class="section-kicker">ВАРІАНТ 1 · ВАРШАВА</div><h3>Пізній Modlin → Варшава → Берлін</h3><div class="booking-line"><span>10.09. · 22:50–23:35</span><b>Wizz Air · RMO → WMI · від 28 €</b></div><div class="booking-line"><span>Пізно 10.09.</span><b>Modlin → Варшава · прибл. 6–8 €</b></div><div class="booking-line"><span>11.09.</span><b>Прогулянка Варшавою + FlixBus до Берліна · від 31,98 €</b></div><p>Увечері лише приїхати й поспати. Наступного ранку — старе місто, Вісла або Прага, потім автобус далі. Це справжня міні-подорож, а не безглузда пересадка.</p><p class="muted">Не дешевше за прямий рейс: сенс у самій Варшаві. Unterkunft bitte separat im Checkout wählen.</p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-WMI/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=WMI&amp;depart=2026-09-10">Перевірити RMO → WMI ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.pl/polaczenia-autobusowe/port-lotniczy-warszawa-modlin-berlin">Перевірити Modlin → Берлін ↗</a></article><article class="day-card"><div class="section-kicker">ВАРІАНТ 2 · БУХАРЕСТ → БУДАПЕШТ</div><h3>Денна зупинка + нічний автобус уздовж Дунаю</h3><div class="booking-line"><span>09.09. · 07:50–08:55</span><b>Wizz Air · RMO → OTP · 29 €</b></div><div class="booking-line"><span>09.09. вдень</span><b>Бухарест: Gara de Nord, Calea Victoriei, Старе місто</b></div><div class="booking-line"><span>09.09. ввечері</span><b>FlixBus · Бухарест → Будапешт · від 52,98 €</b></div><div class="booking-line"><span>10.09.</span><b>День у Будапешті; далі гнучко</b></div><p>Збільшена версія бухарестської зупинки: спочатку чотири години міста, потім нічний автобус і вранці — Будапешт. Гарний дунайський маршрут лише з однією оплачуваною ночівлею — нічний автобус замінює хостел.</p><p class="muted">Точний час нічного автобуса залежить від дати; перевірте його під час оплати. До Мюнхена з Будапешта зараз додати приблизно 43,98 € FlixBus, до Інсбрука потрібен окремий австрійський квиток.</p><a class="place-link" target="_blank" rel="noopener" href="https://flights.booking.com/flights/RMO-OTP/?type=ONEWAY&amp;adults=1&amp;cabinClass=ECONOMY&amp;from=RMO&amp;to=OTP&amp;depart=2026-09-09">Перевірити RMO → OTP ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.de/busverbindung/fernbus-bukarest-budapest">Перевірити Бухарест → Будапешт ↗</a><a class="place-link" target="_blank" rel="noopener" href="https://www.flixbus.de/busverbindung/fernbus-budapest-muenchen">Перевірити Будапешт → Мюнхен ↗</a></article></div></div>`;target.before(section);}
